import{c as t,Q as a,j as r,m as i}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"GetFmaTmpBufferFactorSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetFmaTmpBufferFactorSize","slug":"getfmatmpbufferfactorsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/Fma接口/GetFmaTmpBufferFactorSize.md","filePath":"api/SIMD-API/高阶API/数学计算/Fma接口/GetFmaTmpBufferFactorSize.md"}'),n={name:"api/SIMD-API/高阶API/数学计算/Fma接口/GetFmaTmpBufferFactorSize.md"};function o(p,e,s,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="getfmatmpbufferfactorsize" tabindex="-1">GetFmaTmpBufferFactorSize <a class="header-anchor" href="#getfmatmpbufferfactorsize" aria-label="Permalink to &quot;GetFmaTmpBufferFactorSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>该接口用于获取maxLivedNodeCount和extraBuf，在固定空间大小的情况下，通过maxLivedNodeCount和extraBuf可以推算算子单次最大计算元素数量。maxLivedNodeCount表示临时空间是单次计算数据量所占空间的多少倍；extraBuf表示使用的额外临时空间大小。</p><p>推算示例如下：</p><ul><li><p>算子实现需要调用Fma接口，开发者为其预留currBuff大小的空间，利用GetFmaTmpBufferFactorSize接口得到maxLivedNodeCount、extraBuf输出值，可推导算子单次最大计算元素数量为：</p><p><strong>currentShapeSize = (currBuff - extraBuf) / maxLivedNodeCount / typeSize</strong></p></li><li><p>算子实现需要调用两个kernel侧API KernelIntf1、KernelIntf2，利用两个GetXxxTmpBufferFactorSize（其中Xxx为需要调用的两个高阶API）接口的两组输出值(maxLivedNodeCount、extraBuf)以及当前现有的临时空间，推导单次最大计算元素数量currentShapeSize为：</p><p><strong>currentShapeSize1 = (currBuff - extraBuf1) / maxLivedNodeCount1 / typeSize</strong></p><p><strong>currentShapeSize2 = (currBuff - extraBuf2) / maxLivedNodeCount2 / typeSize</strong></p><p><strong>currentShapeSize = min(currentShapeSize1, currentShapeSize2)</strong></p></li></ul><p>注意上文中的currBuff表示接口计算可用的空间，需要去除用户输入输出等空间；另外，接口获取的maxLivedNodeCount值可能为0，计算时需要判断该值非0，避免除零错误。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetFmaTmpBufferFactorSize(const platform_ascendc::PlatformAscendC&amp; ascendcPlatform, const uint32_t typeSize, uint32_t&amp; maxLivedNodeCount, uint32_t&amp; extraBuf)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数列表</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>ascendcPlatform</td><td>输入</td><td>输入的平台信息。PlatformAscendC的定义请参见构造及析构函数。</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>maxLivedNodeCount</td><td>输出</td><td>最大存活节点数，表示临时空间是单次计算数据量所占空间的多少倍。</td></tr><tr><td>extraBuf</td><td>输出</td><td>使用的额外临时空间大小，单位为字节。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当利用maxLivedNodeCount、extraBuf反推出的currentShapeSize * typeSize &lt; 256B时，currentShapeSize按照256B/typeSize的值向上取整。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的调用样例请参考<a href="./../更多样例-83.html">更多样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t maxLivedNodeCount = 0;</span></span>
<span class="line"><span>uint32_t extraBuf = 0;</span></span>
<span class="line"><span>auto plat = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>AscendC::GetFmaTmpBufferFactorSize(plat, typeSize, maxLivedNodeCount, extraBuf);</span></span></code></pre></div>`,18)])])}const m=t(n,[["render",o]]);export{f as __pageData,m as default};
